PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,entity TEXT NOT NULL REFERENCES entities(id),type TEXT NOT NULL,last4 TEXT,active INTEGER NOT NULL DEFAULT 1,provider_id TEXT UNIQUE,balance_cents INTEGER,currency TEXT DEFAULT 'AUD',synced_at TEXT);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS people(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS trips(id TEXT PRIMARY KEY,name TEXT NOT NULL,start_date TEXT,end_date TEXT);
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),date TEXT NOT NULL,amount_cents INTEGER NOT NULL,raw_description TEXT NOT NULL,merchant TEXT NOT NULL,category_id TEXT REFERENCES categories(id),person_id TEXT REFERENCES people(id),trip_id TEXT REFERENCES trips(id),note TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('income','spend','transfer','debt')),reimbursable INTEGER NOT NULL DEFAULT 0,reimbursed INTEGER NOT NULL DEFAULT 0,parent_id TEXT REFERENCES transactions(id),source TEXT NOT NULL,source_hash TEXT NOT NULL UNIQUE,provider_id TEXT UNIQUE,currency TEXT NOT NULL DEFAULT 'AUD',running_balance_cents INTEGER,reviewed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS tx_date ON transactions(date DESC);
CREATE INDEX IF NOT EXISTS tx_account_date ON transactions(account_id,date);
CREATE TABLE IF NOT EXISTS rules(id TEXT PRIMARY KEY,pattern TEXT NOT NULL,merchant TEXT,category_id TEXT REFERENCES categories(id),person_id TEXT REFERENCES people(id),kind TEXT,entity TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS debts(id TEXT PRIMARY KEY,name TEXT NOT NULL,entity TEXT NOT NULL REFERENCES entities(id),start_cents INTEGER NOT NULL,balance_cents INTEGER NOT NULL,payment_cents INTEGER NOT NULL DEFAULT 0,payment_every TEXT NOT NULL DEFAULT 'month',currency TEXT NOT NULL DEFAULT 'AUD',note TEXT DEFAULT '',annual_minimum_cents INTEGER,next_due TEXT,fx_aud REAL DEFAULT 1);
CREATE TABLE IF NOT EXISTS debt_payments(id TEXT PRIMARY KEY,debt_id TEXT NOT NULL REFERENCES debts(id),amount_cents INTEGER NOT NULL,date TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS imports(id TEXT PRIMARY KEY,file_name TEXT NOT NULL,account_id TEXT,rows_in INTEGER NOT NULL,rows_new INTEGER NOT NULL,rows_skipped INTEGER NOT NULL,status TEXT DEFAULT 'complete',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS credentials(id TEXT PRIMARY KEY,public_key TEXT NOT NULL,counter INTEGER NOT NULL,transports TEXT NOT NULL,user_id TEXT NOT NULL UNIQUE DEFAULT 'demo-user');
CREATE TABLE IF NOT EXISTS challenges(id TEXT PRIMARY KEY,challenge TEXT NOT NULL,kind TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
