INSERT OR IGNORE INTO categories VALUES('income','Income'),('food','Food'),('living','Living costs'),('people','People'),('loan','Loan'),('shopping','Shopping'),('work','Work'),('travel','Travel'),('family','Family'),('subscriptions','Subscriptions'),('car','Car'),('business','Business'),('unsorted','Unsorted');
